    {"대지": "서론", "내용": "아들이 세상에 들어오실 때 천사들이 경배한다. 이는 성탄의 베들레헴 장면이며 재림의 위엄일 수도 있고 부활 승천의 영광일 수도 있다. 어느 경우이든 천사들이 경배하는 분이 아들이시다", "예화_적용": "베들레헴 들판의 천사들이 영광을 노래했다. 그 경배가 지금도 하늘에서 계속되고 있다"},
    {"대지": "1대지: 맏아들의 등장 (우주적 사건)", "내용": "아들이 세상에 들어오심은 우주적 사건이다. 창조주가 피조물 안으로 들어오신 경이의 순간이다", "예화_적용": "왕이 시골 마을을 방문하면 온 마을이 들썩이듯 창조주의 방문은 온 우주를 흔들었다"},
    {"대지": "2대지: 천사들의 경배 (신성의 증거)", "내용": "천사들도 아들에게 경배한다. 이는 아들이 하나님이심의 증거이다. 오직 하나님만 경배의 대상이시다", "예화_적용": "요한이 천사에게 경배하려 하자 천사가 거절했다(계 19:10). 그러나 천사 자신은 아들께 경배한다. 아들은 하나님이시다"},
    {"대지": "3대지: 모든 천사 (우주적 주권)", "내용": "'모든 천사'가 경배한다. 아들의 주권은 일부가 아니라 모든 영적 존재를 포괄한다", "예화_적용": "오늘 하늘에 있는 모든 천군 천사가 어린 양 앞에 엎드린다(계 5:11). 우리도 그 경배에 참여한다"},
    {"대지": "결론", "내용": "천사들이 경배하는 맏아들에게 우리도 경배하자. 매 순간의 예배는 하늘의 경배에 참여하는 것이다", "예화_적용": "주일 예배는 단순한 모임이 아니라 천사들과 함께 맏아들에게 드리는 우주적 경배이다"}
