    {"상황": "그리스도의 주권을 부분적으로 인정하는 성도", "성경원리": "모든 천사가 아들에게 경배한다. 아들의 주권은 전 영역에 미친다. 삶의 일부만 드리는 것은 온전한 경배가 아니다", "실제적용": "삶의 모든 영역(가정, 직장, 경제, 관계)을 그리스도의 주권 아래 놓도록 인도하라"}
