    {"교리": "아들과 천사의 대조", "설명": "아들은 주권자로 보좌에 앉으시고 천사는 사역자로 바람과 불꽃이 된다. 질적으로 다른 범주의 존재이다", "관련구절": "히 1:8, 히 1:13, 엡 1:21, 벧전 3:22"}
