    {"영어원문": "His ministers a flame of fire — zealous, piercing, consuming when sent in judgment.", "한국어번역": "그 사역자들을 불꽃으로 삼으시느니라 - 열정적이며, 꿰뚫고, 심판의 사자로 보내질 때 태우는 자가 된다.", "핵심통찰": "천사는 은혜와 심판 양쪽에서 하나님의 도구이다"}
