    {"대지": "결론", "내용": "천사가 바람과 불꽃이라면 우리는 더욱 열정적인 종이 되자. 자기 자리를 지키며 주님의 뜻에 바람처럼 불꽃처럼 순종하자", "예화_적용": "천사 앞에 부끄러운 성도가 되지 말자. 그들이 우리의 섬김을 지켜본다(고전 4:9)"}
