    {"항목": "'즐거움의 기름'의 상징", "내용": "고대에는 축제 때 향기로운 기름을 머리에 부어 기쁨을 표현했다. 시편 45편은 왕의 결혼식 즐거움에서 이 이미지를 사용한다", "목회적활용": "그리스도 안의 즐거움은 세상이 모방할 수 없는 성령의 기쁨이다"}
