    {"구분": "솔로몬의 결혼", "내용": "시편 45편은 솔로몬의 결혼을 배경으로 하나 궁극적으로는 그리스도와 교회의 혼인을 가리킨다", "그리스도연결": "그리스도는 의를 사랑하시는 신랑이시며 교회는 그분의 신부로서 함께 기름부음에 참여한다(엡 5:25-27)"}
