  "표5_매튜헨리": [
    {"영어원문": "Thou hast loved righteousness and hated iniquity — perfect moral character is the foundation of His kingdom's glory.", "한국어번역": "네가 의를 사랑하고 불법을 미워하였으니 - 완전한 도덕적 성품이 그분 왕국의 영광의 기초이다.", "핵심통찰": "왕국의 영광은 힘에서가 아니라 의로운 성품에서 나온다"},
    {"영어원문": "God, even thy God, hath anointed thee with the oil of gladness above thy fellows — Christ receives the Spirit without measure, His fellows receive Him in measure.", "한국어번역": "하나님 곧 너의 하나님이 즐거움의 기름을 네게 주어 네 동류들보다 승하게 하셨도다 - 그리스도는 한정 없이 성령을 받으시고 그분의 동류들은 분량대로 받는다.", "핵심통찰": "그리스도는 기름부음의 원천이시며 성도는 그분으로부터 분량대로 받는다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "의를 사랑하고 불법을 미워하는 왕 - 즐거움의 기름부음", "예화_적용": "아들의 통치는 무력이 아닌 의로운 성품에 근거한다"},
    {"대지": "서론", "내용": "아들은 의를 사랑하고 불법을 미워하셨다. 그 결과 하나님은 그분에게 동류들보다 승한 즐거움의 기름을 주셨다. 성품이 소명을 결정한다", "예화_적용": "다윗이 하나님 마음에 맞았기에 기름부음을 받았다. 그리스도는 완전한 의의 사람이셨기에 완전한 기름부음을 받으셨다"},
    {"대지": "1대지: 의를 사랑하심 (적극적 성품)", "내용": "아들은 의를 행하실 뿐 아니라 사랑하신다. 의가 그분의 기쁨이요 갈망이요 본성이다", "예화_적용": "강요된 의무는 오래가지 못한다. 사랑에서 나오는 의만이 지속된다. 우리도 의를 사랑하는 수준으로 자라야 한다"},
    {"대지": "2대지: 불법을 미워하심 (소극적 분별)", "내용": "아들은 불법을 미워하신다. 무관심이나 타협이 아니라 분명한 미움이다. 악에 대한 거룩한 분노가 있다", "예화_적용": "불법을 미워하지 않는 사랑은 거짓 사랑이다. 아이를 사랑하는 부모는 아이를 해치는 것을 미워한다"},
    {"대지": "3대지: 즐거움의 기름부음 (거룩한 기쁨)", "내용": "의를 사랑하고 불법을 미워한 결과 즐거움의 기름부음을 받으셨다. 거룩은 무거움이 아니라 기쁨이다", "예화_적용": "세상은 거룩을 고지식과 억압으로 오해하나 성경의 거룩은 깊은 기쁨과 결합된다"},
    {"대지": "결론", "내용": "의를 사랑하는 왕의 동류가 되자. 그분과 함께 기름부음에 참여하자. 우리 안에도 그분의 성품과 기쁨이 나타난다", "예화_적용": "오늘 우리 안에 의를 사랑하는 열정과 즐거움의 기름부음이 함께 흐르고 있다. 그리스도 안에 있기 때문이다"}
  ],
  "표7_찬송가": [
    {"새찬송가": "191", "통일찬송가": "189", "제목": "내가 매일 기쁘게", "선정이유": "즐거움의 기름부음을 받은 성도의 기쁨을 노래한다"},
    {"새찬송가": "408", "통일찬송가": "466", "제목": "어디든지 예수 나를 이끌면", "선정이유": "의를 사랑하시는 주님을 따르는 고백이다"},
    {"새찬송가": "425", "통일찬송가": "217", "제목": "주님의 뜻을 이루소서", "선정이유": "왕의 뜻에 순종하는 동류의 마음을 담는다"},
    {"새찬송가": "432", "통일찬송가": "484", "제목": "너 근심 걱정 말아라", "선정이유": "의로운 왕이 다스리시는 기쁨을 확신한다"}
  ],
  "표8_상담적용": [
    {"상황": "거룩함이 무겁고 답답하다고 느끼는 성도", "성경원리": "의를 사랑하시는 분에게는 즐거움의 기름이 부어졌다. 참된 거룩은 무거움이 아니라 기쁨과 결합된다. 율법주의가 아닌 사랑의 거룩이다", "실제적용": "의무로서의 거룩이 아닌 사랑과 기쁨에서 나오는 거룩을 추구하도록 안내하라"},
    {"상황": "영적 침체와 기쁨 상실을 겪는 성도", "성경원리": "아들의 동류들도 즐거움의 기름부음에 참여한다. 그리스도와의 연합 안에 있으면 기쁨의 기름이 흘러나온다", "실제적용": "그리스도와의 관계를 회복하고 성령의 기름부음을 위해 기도하도록 권면하라"}
  ],
  "표9_교차참조": [
    {"구절": "시 45:7", "연결점": "네가 의를 사랑하고 악을 미워하니 - 직접 인용", "구분": "구약"},
    {"구절": "사 61:1", "연결점": "주 여호와의 신이 내게 임하셨으니 이는 여호와께서 내게 기름을 부으사 - 메시아의 기름부음", "구분": "구약"},
    {"구절": "시 11:7", "연결점": "여호와는 의로우사 의로운 일을 좋아하시나니 - 하나님의 의", "구분": "구약"},
    {"구절": "마 3:16-17", "연결점": "하나님의 성령이 비둘기같이 내려 자기 위에 임하심을 보시더니 - 예수님의 기름부음", "구분": "신약"},
    {"구절": "행 10:38", "연결점": "하나님이 나사렛 예수에게 성령과 능력을 기름 붓듯 하셨으매 - 예수님의 메시아 기름부음", "구분": "신약"},
    {"구절": "고후 1:21", "연결점": "우리에게 기름을 부으신 이는 하나님이시니 - 성도의 기름부음", "구분": "신약"},
    {"구절": "요일 2:20", "연결점": "너희는 거룩하신 자에게서 기름 부음을 받고 - 동류의 기름부음", "구분": "신약"},
    {"구절": "시 97:10", "연결점": "여호와를 사랑하는 너희여 악을 미워하라 - 의와 불법에 대한 태도", "구분": "구약"}
  ]
