    {"원어": "ἱμάτιον (히마티온)", "의미_문법": "옷 - 명사 중성 단수 주격. 외투, 겉옷", "설교포인트": "세상은 옷과 같다. 입었다 벗는 것이며 낡아지는 것이다. 피조물을 옷처럼 취급하시는 창조주의 위엄이다"},
    {"원어": "παλαιωθήσονται (팔라이오데손타이)", "의미_문법": "낡아지리니 - 동사 미래 수동 직설 3인칭 복수. 늙어지다", "설교포인트": "모든 피조물은 낡아간다. 우주의 엔트로피 법칙 뒤에 이미 성경의 진리가 있다"}
