    {"항목": "고대인의 천체관", "내용": "고대인들은 해와 달과 별이 영원히 변치 않는다고 생각했다. 그러나 성경은 하늘조차 낡아진다고 선언한다. 이는 현대 과학의 우주론과 일치한다", "목회적활용": "가장 견고해 보이는 것도 피조물이며 소멸의 운명을 가진다. 참된 안정은 창조주 안에만 있다"}
