    {"원어": "παρακοή (파라코에)", "의미_문법": "순종치 아니함 - 명사 여성 단수 주격. 듣기를 거절함", "설교포인트": "'파라코에'는 말씀을 '듣지 않음'이다. 소극적 불순종도 죄이다. 듣지 않는 것이 이미 죄이다"},
    {"원어": "μισθαποδοσία (미스다포도시아)", "의미_문법": "보응 - 명사 여성 단수 대격. 합당한 보상, 응보", "설교포인트": "하나님의 보응은 공변되다. 공정하고 합당한 응보가 있음을 성경은 선포한다"}
