    {"영어원문": "Every transgression and disobedience received a just recompence — divine justice was exactly rendered under the old covenant.", "한국어번역": "모든 범죄함과 순종치 아니함이 공변된 보응을 받았거든 - 옛 언약 아래서 신적 공의가 정확하게 시행되었다.", "핵심통찰": "하나님의 공의는 빈틈이 없다"}
