    {"대지": "서론", "내용": "저자는 작은 것으로부터 큰 것으로 논증한다(a minori ad maius). 천사의 말씀조차 견고했다면 아들의 말씀은 얼마나 더 견고하겠는가", "예화_적용": "하급 법원의 판결도 효력이 있다면 대법원의 판결은 얼마나 더 엄중한가"},
    {"대지": "1대지: 견고한 말씀 (계시의 확실성)", "내용": "천사로 전달된 율법도 견고했다. 하나님의 말씀은 어느 단계에서도 효력을 잃지 않는다", "예화_적용": "왕의 서신은 전달자가 누구든 왕의 권위로 유효하다. 하나님의 말씀도 마찬가지이다"},
    {"대지": "2대지: 범죄와 불순종 (죄의 두 얼굴)", "내용": "적극적 범죄(파라바시스)와 소극적 불순종(파라코에)이 모두 죄이다. 행하지 말 것을 행하는 것도, 행할 것을 행하지 않는 것도 죄이다", "예화_적용": "불을 지른 자도 죄이지만 불이 났을 때 끄지 않은 자도 책임이 있다. 작위와 부작위 모두 죄이다"},
    {"대지": "3대지: 공변된 보응 (공의의 실현)", "내용": "하나님은 모든 죄에 공정한 보응을 하신다. 구약에서 그러했다면 신약에서는 더 엄중하다", "예화_적용": "부모 앞에서 장난도 벌을 받았거든 하나님 앞에서 영적 장난은 얼마나 무거운 결과를 낳겠는가"},
    {"대지": "결론", "내용": "말씀을 경시하지 말자. 천사의 말씀도 견고했다면 아들의 말씀은 얼마나 더 견고한가. 들은 만큼 책임을 지자", "예화_적용": "큰 은혜 앞에 서 있을수록 작은 불순종도 무겁게 여겨야 한다. 은혜가 무책임의 핑계가 될 수 없다"}
