    {"상황": "적극적 범죄만 죄로 여기는 성도", "성경원리": "범죄함과 함께 '순종치 아니함'도 죄이다. 해야 할 일을 하지 않는 것, 말씀을 듣지 않는 것도 죄이다", "실제적용": "죄의 범위를 성경적으로 확장시켜 적극적 선행과 순종의 책임도 인식하게 하라"}
