    {"교리": "무관심의 치명성", "설명": "적극적 배교가 아니라 소극적 무관심도 심판을 피할 수 없다. 복음을 가볍게 여기는 자는 복음의 은혜에서 제외된다", "관련구절": "마 22:5, 히 10:29, 눅 14:18-24, 계 3:16"}
