    {"항목": "성령 은사의 다양성", "내용": "고린도전서 12장은 성령의 다양한 은사를 나열한다. 각 은사는 성령이 '그 뜻대로' 나눠주신 것이다", "목회적활용": "다양한 은사는 교회의 건강한 다양성을 만든다. 획일화가 아닌 다양성의 조화가 성령의 방식이다"}
