    {"교리": "성령의 주권적 분배", "설명": "성령은 '그 뜻을 따라' 은사를 나눠주신다. 인간의 선택이나 노력이 아니라 성령의 주권적 분배이다", "관련구절": "고전 12:11, 엡 4:7, 롬 12:6, 벧전 4:10"}
