    {"영어원문": "Gifts of the Holy Ghost, according to His own will — the Spirit distributes His gifts sovereignly, not according to human desire.", "한국어번역": "자기 뜻을 따라 성령의 나눠 주신 것으로 - 성령은 인간의 욕망이 아니라 주권적으로 그분의 은사를 분배하신다.", "핵심통찰": "성령은 주권자이시며 은사의 주인이시다"}
