    {"구분": "다윗의 확장된 왕국", "내용": "다윗은 이스라엘의 왕으로 이방 민족까지 통치 범위를 확장했다. 그러나 그의 왕국도 한시적이었다", "그리스도연결": "그리스도는 참된 다윗의 왕으로 온 우주를 영원히 통치하신다(단 7:14)"}
