    {"원어": "ἀνυπότακτον (아뉘포탁톤)", "의미_문법": "복종치 않은 - 형용사 중성 단수 대격 부정. 복종하지 않은 상태", "설교포인트": "하나님의 시각에서 아직 복종하지 않은 것이 없다. 모든 것이 이미 결정되었다"},
    {"원어": "οὔπω (우포)", "의미_문법": "아직 - 부사. 시간적으로 아직", "설교포인트": "'아직'은 이미와 아직의 긴장을 보여준다. 구속은 이미 이루어졌으나 현실에서 아직 완성되지 않았다"}
