    {"대지": "2대지: 현실의 간격 (아직의 현실)", "내용": "그러나 지금 만물의 완전한 복종을 보지 못한다. 세상에는 여전히 악과 무질서가 있다", "예화_적용": "승리한 나라도 저항하는 게릴라를 완전히 제압하기까지 시간이 걸린다. 사탄의 저항도 아직 남아있다"},
    {"대지": "3대지: 믿음의 시각 (영원의 눈)", "내용": "믿음은 아직 보이지 않는 것을 본다. 그리스도의 완성된 주권을 믿음의 눈으로 바라본다", "예화_적용": "망원경이 멀리 있는 것을 가까이 보여주듯 믿음은 장차 올 왕국을 현재에 끌어당긴다"},
    {"대지": "결론", "내용": "이미와 아직 사이에서 믿음으로 서자. 법적 승리를 의지하고 완전한 성취를 기다리며 오늘을 살자", "예화_적용": "오늘의 혼란에 압도되지 말자. 왕은 이미 즉위하셨다. 그분의 왕국은 필연적으로 완성될 것이다"}
