    {"교리": "은혜의 주도성", "설명": "구속은 하나님의 은혜로 이루어졌다. 인간의 공로가 아니라 하나님의 사랑의 주도적 행동이다", "관련구절": "엡 2:8-9, 롬 3:24, 딛 3:5, 롬 5:15"}
