    {"새찬송가": "149", "통일찬송가": "147", "제목": "주 달려 죽은 십자가", "선정이유": "죽음을 맛보신 주를 노래한다"},
    {"새찬송가": "150", "통일찬송가": "139", "제목": "갈보리산 위에", "선정이유": "모든 사람을 위한 죽음을 찬양한다"},
    {"새찬송가": "305", "통일찬송가": "405", "제목": "나 같은 죄인 살리신", "선정이유": "은혜로 인한 구속의 감격을 담는다"}
