    {"대지": "서론", "내용": "하나님의 경륜은 그분의 지혜에 합당하다. 많은 아들들을 영광에 이끄시는 일에 구원의 개척자를 고난으로 완성시키는 것이 합당했다. 그리스도는 우리의 길을 먼저 걸으셨다", "예화_적용": "등반대의 지도자는 가장 먼저 험한 길을 개척한다. 그리스도는 구원의 험한 길을 먼저 개척하신 우리의 대장이시다"},
    {"대지": "1대지: 합당한 경륜 (하나님의 지혜)", "내용": "고난의 길은 합당한 길이었다. 하나님의 지혜와 사랑에 어울리는 방법이었다", "예화_적용": "부모가 자녀를 훈련시키는 방법이 부모의 사랑에 합당하듯 하나님이 그리스도를 완성시키는 방법도 그분의 성품에 합당했다"},
    {"대지": "2대지: 구원의 개척자 (앞서 가는 주)", "내용": "그리스도는 구원의 개척자(아르케고스)이시다. 우리가 갈 길을 먼저 걸으셨고 많은 아들들을 그 길로 이끄신다", "예화_적용": "셀파는 등반가를 위해 먼저 길을 내고 로프를 걸어둔다. 그리스도는 구원의 셀파로서 우리의 안전한 등반을 위한 모든 길을 먼저 만드셨다"},
    {"대지": "3대지: 고난을 통한 온전함 (경험의 완성)", "내용": "그리스도는 고난을 통해 구속주의 자격에 있어 온전케 되셨다. 고난의 경험이 우리를 공감하시는 대제사장의 자격이 되었다", "예화_적용": "같은 병을 앓은 의사가 환자를 가장 잘 이해한다. 고난을 통과하신 그리스도가 우리의 고난을 가장 깊이 이해하신다"},
    {"대지": "결론", "내용": "구원의 개척자를 따라가자. 그분이 열어놓으신 고난과 영광의 길을 걸어가자. 혼자가 아니라 많은 형제와 함께이다", "예화_적용": "개척자를 따라가면 길을 잃지 않는다. 그리스도를 따르는 자는 반드시 영광에 이른다"}
