    {"대지": "서론", "내용": "그리스도는 거룩케 하시는 분이시며 우리는 거룩케 함을 입은 자이다. 이 둘은 한 근원에서 났다. 그래서 그리스도는 우리를 형제라 부르시기를 부끄러워하지 않으신다", "예화_적용": "왕자가 가난한 아이를 '내 형제'라 부르기 쉽지 않다. 그러나 우주의 왕이신 그리스도는 우리를 형제라 부르신다"},
    {"대지": "1대지: 한 근원에서 남 (연합의 실재)", "내용": "그리스도와 성도는 한 근원에서 났다. 성육신으로 한 혈육이 되셨고 한 아버지의 자녀가 되었다", "예화_적용": "입양된 자녀가 부모의 친자와 같은 권리를 가진다. 그리스도 안에서 우리도 하나님의 친자와 같은 권리를 가진다"},
    {"대지": "2대지: 거룩케 하시는 자와 받는 자 (관계의 본질)", "내용": "그리스도는 주도자이시고 우리는 수혜자이다. 거룩함은 받는 것이다. 자기 노력의 산물이 아니다", "예화_적용": "스스로 깨끗해진 옷이 없듯 스스로 거룩해진 사람도 없다. 그리스도께서 씻으실 때에만 거룩해진다"},
    {"대지": "3대지: 부끄러워하지 아니하심 (사랑의 확증)", "내용": "우리의 죄와 약함에도 그리스도는 우리를 형제라 부르기를 부끄러워하지 않으신다. 이것이 놀라운 사랑이다", "예화_적용": "진짜 친구는 부끄러운 순간에도 '내 친구'라 말해준다. 그리스도는 우리의 가장 부끄러운 순간에도 '내 형제'라 말하신다"},
    {"대지": "결론", "내용": "그리스도의 형제로서 당당히 서자. 그분이 부끄러워하지 않으시는 자가 왜 자신을 부끄러워하겠는가", "예화_적용": "왕의 형제로 불리는 자는 누구에게도 주눅들 필요가 없다. 그리스도의 형제된 우리의 신분을 자랑하자"}
