    {"영어원문": "Behold I and the children which God hath given me — believers are the gift of the Father to the Son, and the Son owns them as His own.", "한국어번역": "볼지어다 나와 하나님께서 내게 주신 자녀라 - 믿는 자들은 아버지께서 아들에게 주신 선물이며 아들은 그들을 자기 것으로 인정하신다.", "핵심통찰": "구원의 기초는 아버지의 수여이다"}
