    {"원어": "ὅλῳ τῷ οἴκῳ αὐτοῦ (홀로 토 오이코 아우투)", "의미_문법": "그의 온 집에서 - 명사구. 하나님의 가족 전체", "설교포인트": "'하나님의 집'은 그분의 백성 공동체이다. 구약의 이스라엘과 신약의 교회를 포함한다"}
