    {"대지": "서론", "내용": "모세의 영광은 인정되나 그 영광은 '증거자'의 영광이었다. 그는 사환으로서 장차 오실 그리스도를 가리키는 증거였다", "예화_적용": "이정표는 목적지가 아니라 목적지를 가리킨다. 모세는 가장 빛나는 이정표였고 그 이정표가 가리킨 목적지가 그리스도이시다"},
    {"대지": "1대지: 사환으로서의 모세 (종의 영예)", "내용": "모세는 '사환(테라폰)'이었다. 존귀한 시종이었으나 여전히 종이었다", "예화_적용": "왕의 최측근 시종도 왕자가 아니다. 모세의 영광은 시종의 영광이며 그리스도는 아들의 영광이시다"},
    {"대지": "2대지: 충성된 사환 (종의 미덕)", "내용": "모세는 충성된 사환이었다. 종의 본분을 다했다. 그 자체로 큰 영예이다", "예화_적용": "종의 자리에서 충성되게 섬기는 것이 참된 영예이다. 모세처럼 충성된 종이 되자"},
    {"대지": "3대지: 장래의 증거 (증거자의 사명)", "내용": "모세의 모든 사역은 '장래의 말할 것'에 대한 증거였다. 그는 그리스도를 가리켰다", "예화_적용": "세례 요한은 '나는 그리스도가 아니다. 그를 증거하러 왔다'고 고백했다(요 1:20, 23). 모든 하나님의 종의 자세이다"},
    {"대지": "결론", "내용": "우리도 모세처럼 그리스도를 가리키는 증거자가 되자. 우리의 삶이 그리스도를 드러내는 이정표가 되게 하자", "예화_적용": "달이 빛나는 것은 태양 때문이다. 우리가 빛나는 것은 그리스도 때문이다. 우리의 빛이 그분을 가리키게 하자"}
