    {"항목": "성령의 저자성", "내용": "히브리서 저자는 시편 95편을 '성령이 이르신 것'이라 한다. 이는 성경 영감의 교리의 중요한 증거이다. 인간 저자 배후에 성령이 계신다", "목회적활용": "성경을 읽는다는 것은 성령의 음성을 듣는 것이다. 수동적 독서가 아닌 영적 경청이 필요하다"}
