    {"교리": "현재적 음성", "설명": "성령은 고대의 음성만이 아니라 '오늘' 음성이시다. 성경을 통해 지금도 말씀하신다", "관련구절": "요 16:13, 계 2:7, 히 4:12, 행 28:25"}
