    {"항목": "고대의 상호 권면 문화", "내용": "초대교회는 형제간의 상호 권면을 중요시했다. 바울의 서신들, 사도들의 권면, 성도들 간의 격려가 교회의 동력이었다", "목회적활용": "현대 교회도 상호 권면과 격려의 문화를 회복해야 한다. 영적 성숙은 공동체 안에서 이루어진다"}
