    {"원어": "ἀρχὴν τῆς ὑποστάσεως (아르켄 테스 휘포스타세오스)", "의미_문법": "시작의 확신 - 명사구. 처음의 확신", "설교포인트": "'휘포스타시스'는 '근본, 확신'이다. 신앙의 시작의 확신이다. 이 확신을 끝까지 지켜야 한다"},
    {"원어": "μέχρι τέλους (메크리 텔루스)", "의미_문법": "끝까지 - 전치사구. 종말까지", "설교포인트": "견딤은 '끝까지'여야 한다. 중간에서 멈추는 것은 견딤이 아니다. 완주가 견딤의 증거이다"}
