    {"항목": "견인의 교리적 배경", "내용": "칼빈주의의 견인 교리는 '참된 신자는 끝까지 견딘다'는 것이다. 히브리서 3:14은 이 교리의 중요한 근거이다. 견딤이 참됨의 증거이다", "목회적활용": "구원의 확신은 현재의 견딤에서 드러난다. 시작만이 아니라 지속이 중요하다"}
