    {"새찬송가": "351", "통일찬송가": "389", "제목": "믿음의 새 빛을", "선정이유": "순종의 들음을 결단한다"},
    {"새찬송가": "381", "통일찬송가": "424", "제목": "나 캄캄한 밤 죄의 길에", "선정이유": "반역에서 돌이키는 은혜를 노래한다"},
    {"새찬송가": "214", "통일찬송가": "349", "제목": "나 주의 도움 받고자", "선정이유": "도우심으로 순종하는 결단을 담는다"}
