    {"교리": "죄의 결과", "설명": "죄는 반드시 결과를 낳는다. 광야의 시체들은 죄의 결과의 실재를 증거한다", "관련구절": "롬 6:23, 갈 6:7-8, 약 1:15, 겔 18:20"}
