    {"영어원문": "Whose carcases fell in the wilderness — the wilderness became a graveyard of unbelief.", "한국어번역": "그 시체가 광야에 엎드러진 - 광야가 불신앙의 묘지가 되었다.", "핵심통찰": "불신앙의 결말은 실재적 죽음이다"}
