    {"구절": "히 4:6", "연결점": "순종치 아니함을 인하여 들어가지 못하였으므로 - 재확인", "구분": "신약"},
    {"구절": "롬 11:30", "연결점": "너희가 전에 하나님께 순종치 아니하더니 - 불순종의 상태", "구분": "신약"},
    {"구절": "엡 2:2-3", "연결점": "순종치 아니하는 아들들 가운데서 역사하는 영이라 - 불순종의 영", "구분": "신약"},
    {"구절": "살후 1:8", "연결점": "우리 주 예수의 복음을 복종치 않는 자들에게 형벌을 주시리니 - 불순종의 심판", "구분": "신약"},
    {"구절": "벧전 2:7-8", "연결점": "순종치 아니하는 자에게는 - 불순종의 결과", "구분": "신약"},
    {"구절": "약 2:17", "연결점": "믿음도 그 자체가 죽은 것이라 - 행함 없는 믿음", "구분": "신약"},
    {"구절": "요 3:36", "연결점": "아들에게 순종치 아니하는 자는 영생을 보지 못하고 - 불순종의 결과", "구분": "신약"}
