    {"항목": "'두려움'의 성경적 개념", "내용": "성경은 '여호와를 경외하는 것이 지혜의 근본'이라 말한다(잠 9:10). 이 두려움은 공포가 아니라 경외와 존경이다", "목회적활용": "하나님에 대한 건강한 두려움은 방종을 막고 순종을 격려한다. 오늘날 잃어버린 덕목이다"}
