    {"대지": "서론", "내용": "이스라엘도 복음을 받았으나 유익이 없었다. 왜? 듣는 자가 믿음으로 받지 않았기 때문이다. 말씀과 믿음의 결합이 핵심이다", "예화_적용": "좋은 약도 복용하지 않으면 치료되지 않는다. 말씀도 믿음으로 받지 않으면 효력이 없다"},
    {"대지": "1대지: 복음은 주어진다 (객관적 실재)", "내용": "광야의 이스라엘에게도, 우리에게도 복음이 전해졌다. 객관적으로 동일한 복음이 주어진다", "예화_적용": "같은 태양이 모든 땅에 비친다. 같은 복음이 모든 사람에게 전해진다. 문제는 받는 자의 태도이다"},
    {"대지": "2대지: 들음의 한계 (표면적 반응)", "내용": "들음만으로는 유익이 없다. 소리가 귀에 도달해도 마음에 이르지 않으면 변화가 없다", "예화_적용": "라디오 소리를 듣고도 내용을 놓치는 경우가 있다. 귀로 듣는 것과 마음으로 듣는 것은 다르다"},
    {"대지": "3대지: 믿음과의 화합 (변화의 열쇠)", "내용": "말씀이 믿음과 섞여야 한다. 두 요소가 결합될 때 능력이 발휘된다. 믿음은 말씀을 삶으로 옮기는 통로이다", "예화_적용": "물과 기름은 섞이지 않는다. 그러나 유화제를 넣으면 섞인다. 믿음이 말씀을 우리 삶에 섞이게 하는 유화제이다"},
    {"대지": "결론", "내용": "말씀을 들을 때 믿음으로 받자. 믿음 없이 듣는 말씀은 소음일 뿐이다. 믿음과 결합된 말씀이 생명이 된다", "예화_적용": "오늘 읽은 말씀이 어떻게 나의 믿음과 결합되고 있는가? 결합되지 않으면 효력이 없다"}
