    {"대지": "3대지: 창세부터의 준비 (영원한 경륜)", "내용": "안식은 창세부터 준비된 것이다. 하나님의 영원한 경륜에 의한 것이며 우연이 아니다", "예화_적용": "부모가 자녀의 방을 미리 준비해 두듯 하나님은 우리를 위한 안식을 영원 전부터 준비하셨다"},
    {"대지": "결론", "내용": "믿음으로 오늘 안식에 들어가자. 창세 전부터 준비된 안식이 우리를 기다린다. 들어가는 자가 복되다", "예화_적용": "오늘 나의 불안과 조급함을 내려놓고 그리스도 안의 안식에 들어가자. 그것이 신앙의 은혜이다"}
