    {"구절": "민 14:23", "연결점": "내가 그들의 열조에게 맹세한 땅에 결단코 들어가지 못할 것이요 - 역사적 성취", "구분": "구약"},
    {"구절": "벧후 3:1", "연결점": "진실한 마음을 일깨워 - 반복의 각성 효과", "구분": "신약"}
