    {"원어": "κατέπαυσεν (카테파우센)", "의미_문법": "안식을 주었더면 - 아오리스트 능동 직설 3인칭 단수. 쉬게 했더면", "설교포인트": "여호수아가 '안식을 주었다'. 그러나 완전한 안식은 아니었다. 조건절이 이를 보여준다"},
    {"원어": "οὐκ ἂν ... ἐλάλει (우크 안 엘랄레이)", "의미_문법": "말씀하지 아니하셨으리라 - 미완료 능동 직설 3인칭 단수 부정. 말씀하지 않았을 것이다", "설교포인트": "가정법적 구조. 완전한 안식이 주어졌다면 다시 언급할 필요가 없었을 것이다"},
    {"원어": "ἄλλης ἡμέρας (알레스 헤메라스)", "의미_문법": "다른 날 - 형용사 + 명사. 또 다른 날", "설교포인트": "'다른 날'은 다윗 시대의 '오늘'을 가리킨다. 이는 여호수아의 안식이 완전한 안식이 아니었음을 증거한다"}
