    {"항목": "히브리어-헬라어 이름 동일성", "내용": "구약의 여호수아와 신약의 예수는 동일한 이름이다(예슈아 → 이에수스). 이는 두 인물 사이의 예표론적 관계를 강조한다", "목회적활용": "구약의 인물들의 이름과 역할에서 그리스도의 예표를 발견하는 눈을 가져야 한다"}
