    {"교리": "진정한 안식의 미완성", "설명": "구약의 어떤 안식도 완전하지 않았다. 진정한 안식은 그리스도 안에서 완성된다", "관련구절": "히 4:9, 마 11:28-29, 계 14:13, 사 11:10"}
