    {"영어원문": "He would not have spoken of another day — the need for another day proves the incompleteness of the first.", "한국어번역": "그 후에 다른 날을 말씀하지 아니하셨으리라 - 또 다른 날의 필요성은 첫 안식의 불완전함을 증명한다.", "핵심통찰": "구약의 모든 안식은 신약의 완성을 가리킨다"}
