    {"대지": "2대지: 다른 날의 선언 (지속되는 약속)", "내용": "다윗 시대에 '다시 오늘'이 있었다. 이는 여호수아의 안식이 완전하지 않음을 증거한다", "예화_적용": "광고가 반복되는 것은 아직 목표가 달성되지 않았기 때문이다. '오늘' 초청의 반복은 안식이 아직 완성되지 않았음을 뜻한다"},
    {"대지": "3대지: 예수의 완전한 안식 (궁극적 성취)", "내용": "참된 안식은 예수(이에수스=여호수아) 안에서 완성된다. 이름은 같으나 사역은 다르다", "예화_적용": "가나안 땅은 잃어버릴 수 있었으나 그리스도 안의 안식은 잃지 않는다. 완전한 안식은 그분 안에 있다"},
    {"대지": "결론", "내용": "예수 안의 완전한 안식을 구하자. 구약의 안식으로 만족하지 말고 그리스도께 나아가자", "예화_적용": "오늘 그리스도 안에 들어가 참된 안식을 누리자. 그분이 참된 여호수아이시다"}
