    {"교리": "종말론적 안식", "설명": "남아있는 안식은 종말론적 완성의 안식이다. 이는 현재의 일부이자 미래의 완성이다", "관련구절": "계 14:13, 계 21:3-4, 마 11:28-29, 고후 5:1-4"}
