    {"교리": "하나님을 본받는 안식", "설명": "성도의 안식은 하나님의 안식을 본받는 것이다. 창조를 마치신 하나님처럼 구속을 이루신 그리스도 안에서 쉰다", "관련구절": "창 2:2-3, 마 11:29, 요 19:30, 히 10:12"}
