    {"대지": "2대지: 모든 일에 시험받으심 (경험의 대제사장)", "내용": "그리스도는 '모든 일에' 시험받으셨다. 우리가 겪는 어떤 시험도 그분이 경험하지 못한 것이 없다", "예화_적용": "상담자가 자기가 겪은 문제만 상담할 수 있다. 그리스도는 모든 시험을 겪으셨기에 모든 상담을 하실 수 있다"},
    {"대지": "3대지: 죄는 없으심 (완전의 대제사장)", "내용": "시험받으셨으나 죄가 없으시다. 이 무죄성이 그분의 완전한 속죄의 기초이다", "예화_적용": "같은 바이러스에 감염된 의사는 다른 환자를 치료할 수 없다. 그리스도는 죄의 바이러스에 감염되지 않으셨기에 우리를 구원하실 수 있다"},
    {"대지": "결론", "내용": "공감하시고 무죄하신 대제사장 앞에 나아가자. 그분 앞에서는 위선 없이, 그분 안에서는 죄의 결박 없이 살 수 있다", "예화_적용": "나의 가장 약한 부분을 그리스도께 보이자. 그분은 멀리 계시지 않고 가까이 체휼하시는 분이시다"}
