    {"항목": "인간 대제사장의 한계", "내용": "인간 대제사장은 사람 가운데서 취해진 자이다. 이는 공감의 자격이면서 동시에 한계이기도 하다. 자신도 죄인이기에 자기 죄를 먼저 속해야 했다", "목회적활용": "구약 대제사장의 한계가 그리스도 대제사장의 필요성을 드러낸다"}
