    {"영어원문": "For that he himself also is compassed with infirmity — infirmity is the priest's own garment.", "한국어번역": "자기도 연약에 싸여 있음이니라 - 연약함은 제사장 자신의 옷이다.", "핵심통찰": "연약함 속의 공감이 진정한 제사장의 덕이다"}
