    {"새찬송가": "167", "통일찬송가": "167", "제목": "하나님의 나팔소리", "선정이유": "아버지께서 세우신 아들을 고백한다"},
    {"새찬송가": "170", "통일찬송가": "161", "제목": "내 주님 가신 그 길", "선정이유": "순종의 길을 노래한다"},
    {"새찬송가": "173", "통일찬송가": "165", "제목": "나의 죄를 씻기는", "선정이유": "대제사장의 사역을 찬양한다"}
