    {"상황": "자신의 사역이 인정받지 못해 좌절하는 성도", "성경원리": "그리스도의 영광은 아버지가 주셨다. 인간의 인정이 아닌 하나님의 인정이 중요하다. 인정은 그분의 시간에 온다", "실제적용": "인간의 인정보다 하나님의 인정을 구하도록 초점을 전환하고 기다리는 은혜를 배우도록 돕라"}
