    {"원어": "θεμέλιον (데멜리온)", "의미_문법": "터 - 명사 남성 단수 대격. 기초, 터전", "설교포인트": "초보는 '터'이다. 건물의 기초처럼 중요하지만 기초만 세워서는 집이 되지 않는다"},
    {"원어": "μετανοίας (메타노이아스)", "의미_문법": "회개 - 명사 여성 단수 속격. 마음의 변화", "설교포인트": "'메타노이아'는 '마음의 변화'이다. 기초 교리의 첫 번째는 회개이다. 돌이킴이 신앙의 시작이다"}
