    {"항목": "'버리고 나아감'의 의미", "내용": "이 표현은 기초를 부정하는 것이 아니라 기초를 기초로 삼아 더 쌓아 올린다는 의미이다. 기초에 집착하여 그 이상으로 나아가지 못하는 것이 문제이다", "목회적활용": "복음의 기초는 견고해야 하나 평생 기초만 반복해서는 안 된다. 기초 위에 성숙을 쌓아 올려야 한다"}
