    {"원어": "φωτισθέντας (포티스덴타스)", "의미_문법": "비췸을 얻다 - 아오리스트 수동 분사 복수. 조명을 받다", "설교포인트": "'포티조'는 '빛을 비추다, 깨우치다'이다. 복음의 진리가 마음에 빛처럼 비추어진 경험이다"},
    {"원어": "γευσαμένους (규사메누스)", "의미_문법": "맛보고 - 아오리스트 중간 분사 복수. 체험하다, 맛보다", "설교포인트": "'규오마이'는 '맛보다, 체험하다'이다. 이론적 앎이 아닌 체험적 앎이다"},
    {"원어": "μετόχους πνεύματος ἁγίου (메토쿠스 프뉴마토스 하기우)", "의미_문법": "성령에 참예한 자 - 명사 복수 + 속격. 성령에 동참한 자들", "설교포인트": "'메토코이'는 '동참자'이다. 성령의 역사에 어떤 방식으로든 참여한 자이다"}
