    {"항목": "'비췸'의 초대교회 용례", "내용": "초대교회 일부 문헌에서 '비췸'은 세례와 연결되기도 했다. 세례를 통해 복음의 빛을 받는 경험을 의미했다", "목회적활용": "기독교 입문의 경험들이 나열된다. 이 경험이 있다고 해서 구원이 보장되는 것은 아니다"}
