    {"항목": "팔레스타인의 불로 태우는 관습", "내용": "농부는 가시덤불로 덮인 땅을 태워 새 경작지로 만들었다. 불이 깨끗케 하는 기능을 했다", "목회적활용": "영적 불사름은 심판의 이미지이다. 그러나 동시에 정화의 가능성도 포함될 수 있다"}
