    {"구절": "벧후 2:20-22", "연결점": "개가 그 토하였던 것에 돌아가고 - 돌아간 자의 비극", "구분": "신약"},
    {"구절": "고전 9:27", "연결점": "내가 다른 사람에게 전파한 후에 자기가 도리어 버리움이 될까 - 버림의 위험", "구분": "신약"},
    {"구절": "고후 13:5", "연결점": "너희는 믿음에 있는가 너희 자신을 시험하고 - 자기 점검", "구분": "신약"}
