    {"대지": "1대지: 간절한 바람 (목회적 열망)", "내용": "저자는 간절히 원한다. 모든 성도의 성장에 대한 깊은 열망이다. 이것이 목회자의 마음이다", "예화_적용": "단 한 명도 잃지 않기를 원하는 것이 목자의 마음이다. 저자의 마음도 그러하다"},
    {"대지": "2대지: 부지런의 필요 (지속의 태도)", "내용": "시작의 열심이 아니라 지속의 부지런함이 필요하다. 나태가 소망을 희미하게 한다", "예화_적용": "운동선수는 경기가 끝날 때까지 속도를 유지해야 한다. 영적 경기도 끝까지 부지런해야 한다"},
    {"대지": "3대지: 소망의 풍성함 (확신의 성숙)", "내용": "소망이 '풍성함'에 이른다. 이는 흔들림 없는 확신의 상태이다. 성숙한 소망이다", "예화_적용": "새내기 선원은 불안해하지만 숙련된 선장은 폭풍 속에서도 확신을 가진다. 성숙한 소망도 그러하다"},
    {"대지": "결론", "내용": "끝까지 부지런하자. 소망의 풍성함에 이르자. 시작만 아니라 완주가 중요하다", "예화_적용": "오늘 나의 소망은 얼마나 풍성한가? 흔들리지 않는 확신으로 자라고 있는가?"}
