    {"대지": "서론", "내용": "저자는 앞의 주제(약속을 기업으로 받음)를 이어간다. 아브라함에게 하신 하나님의 약속이 중심 예이다. 하나님은 자기를 두고 맹세하셨다", "예화_적용": "왕이 자기 이름을 걸고 약속한다면 그 약속은 반드시 이루어진다. 하나님이 자기를 두고 맹세하셨다"},
    {"대지": "1대지: 아브라함의 약속 (언약의 기초)", "내용": "하나님이 아브라함에게 약속하셨다. 이 아브라함 언약이 모든 성경적 약속의 기초이다", "예화_적용": "가계의 기초가 되는 인물이 있듯 신앙의 기초가 되는 인물은 아브라함이다"},
    {"대지": "2대지: 더 큰 자가 없음 (하나님의 절대성)", "내용": "하나님보다 더 큰 자는 없다. 그분을 능가할 존재가 없다. 이것이 유일한 하나님의 본성이다", "예화_적용": "판사보다 더 높은 판사가 있을 때 항소할 수 있다. 하나님의 판결은 항소할 상급 법원이 없다"},
    {"대지": "3대지: 자기를 가리켜 맹세 (최고의 확증)", "내용": "하나님은 자기 자신을 두고 맹세하신다. 이것이 가능한 최고의 확증이다", "예화_적용": "자기 이름을 걸고 약속하는 사람은 그 약속을 반드시 지킨다. 하나님의 자기 맹세는 그 이상이다"},
    {"대지": "결론", "내용": "하나님의 맹세에 근거한 약속을 붙잡자. 그분의 자기 맹세 이상의 확증은 없다. 절대적으로 안전하다", "예화_적용": "오늘 흔들리는 상황에서도 하나님의 맹세의 약속을 붙잡자. 그것이 우리의 반석이다"}
