    {"새찬송가": "543", "통일찬송가": "342", "제목": "어려운 일 당할 때", "선정이유": "하나님의 맹세에 의지하는 신앙이다"},
    {"새찬송가": "301", "통일찬송가": "456", "제목": "지금까지 지내 온 것", "선정이유": "신실하신 하나님을 찬양한다"}
