    {"항목": "히브리 강조법", "내용": "히브리어는 같은 단어를 반복하여 강조한다. '복 주고 복 주며', '번성케 하고 번성케 하리라' 이런 표현은 강한 강조이다", "목회적활용": "하나님의 약속은 단순 약속이 아니라 강조된 약속이다. 그 강도와 확실성을 느껴야 한다"}
