    {"교리": "약속 성취의 확실성", "설명": "오래 참은 자에게 약속이 성취된다. 하나님의 약속은 늦을 수 있으나 반드시 이루어진다", "관련구절": "합 2:3, 벧후 3:9, 눅 18:7-8, 히 10:37"}
