    {"구분": "다윗의 기다림", "내용": "다윗은 기름부음 받고 왕위에 오르기까지 많은 해를 기다렸다. 오래 참음 후 약속이 이루어졌다", "그리스도연결": "그리스도는 아버지의 뜻을 이루기까지 기다리셨다. 그분의 재림을 우리도 기다린다"}
