    {"상황": "즉각적인 결과를 원하는 조급한 성도", "성경원리": "약속 성취에는 시간이 필요하다. 성급함은 약속을 놓치게 할 수 있다. 하나님의 시간을 존중해야 한다", "실제적용": "하나님의 타이밍을 신뢰하고 자기 시간표가 아닌 그분의 시간표를 따르도록 안내하라"}
