    {"항목": "성전의 휘장", "내용": "성전 휘장은 지성소와 성소를 구분했다. 대제사장만이 일 년에 한 번 휘장을 지나 지성소에 들어갔다", "목회적활용": "그리스도의 죽음으로 휘장이 찢어졌다(마 27:51). 이제 우리의 소망의 닻이 하늘의 지성소에 이른다"}
